import { languagesInScript, type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import type { StoredNotebook } from '@/db/schema.js';
import { OFFERED_LANGUAGES, type Destination } from './route.js';
import styles from './NotebookRoute.module.css';

/**
 * Where what you are writing is about to go.
 *
 * It appears only when it has something to say. With one notebook there is
 * nothing to decide; with several and an unambiguous script there is nothing
 * to ask, so it states the answer quietly and offers to change it. It raises
 * its voice for exactly one case: the words are in a language none of the
 * notebooks holds, which is not a mistake the learner made but a notebook
 * they have not made yet.
 */
export function NotebookRoute({
  destination,
  chosen,
  onChoose,
  onMake,
}: {
  destination: Destination;
  /** The notebook the words will go to as things stand. */
  chosen: StoredNotebook | undefined;
  onChoose: (notebook: StoredNotebook) => void;
  /** Opens the new-notebook flow, with a language already in mind. */
  onMake: (language: LanguageCode | undefined) => void;
}): React.JSX.Element | null {
  if (destination.kind === 'missing') {
    const offered = languagesInScript(destination.script).slice(0, OFFERED_LANGUAGES);
    return (
      <div className={cx(styles.box, styles.missing)} role="status">
        <p className={styles.title}>{t('route.missingTitle')}</p>
        <p className={styles.body}>{t('route.missingBody', { script: t(`script.${destination.script}`) })}</p>
        <div className={styles.offers}>
          {offered.map((language) => (
            <button
              key={language}
              type="button"
              className={styles.offer}
              onClick={() => {
                onMake(language);
              }}
            >
              {t('route.make', { language: LANGUAGE_NAMES[language] })}
            </button>
          ))}
          {offered.length === 0 && (
            <button
              type="button"
              className={styles.offer}
              onClick={() => {
                onMake(undefined);
              }}
            >
              {t('route.makeOther')}
            </button>
          )}
        </div>
      </div>
    );
  }

  if (destination.kind === 'ask' && destination.notebooks.length > 1) {
    return (
      <div className={styles.box}>
        <span className={styles.label}>{t('route.which')}</span>
        <div className={styles.choices} role="radiogroup" aria-label={t('route.which')}>
          {destination.notebooks.map((notebook) => (
            <button
              key={notebook.id}
              type="button"
              role="radio"
              aria-checked={notebook.id === chosen?.id}
              className={cx(styles.choice, notebook.id === chosen?.id && styles.choiceOn)}
              onClick={() => {
                onChoose(notebook);
              }}
            >
              <span dir="auto">{notebook.title}</span>
              <span className={styles.pair}>{LANGUAGE_NAMES[notebook.targetLang]}</span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  // Certain, and not the notebook being shown: worth one quiet line, because
  // a word that silently lands somewhere else is a word somebody loses.
  if (destination.kind === 'certain' && chosen !== undefined) {
    return (
      <p className={styles.line} role="status">
        <Icon name="notebook" size={14} weight={2} />
        {t('route.goesTo')}: <span dir="auto">{chosen.title}</span>
      </p>
    );
  }

  return null;
}
