import { couldBe, scriptOf, type LanguageCode, type Script } from '@lexpad/core';
import type { StoredNotebook } from '@/db/schema.js';

/**
 * Which notebook a piece of text belongs in.
 *
 * Adding a Persian word to an English notebook is the kind of mistake that
 * is invisible until practice starts and then very annoying to undo, and it
 * is exactly the mistake somebody makes when they keep two notebooks and
 * forget which one is showing. So the text is read before it is filed.
 *
 * What this will not do is guess. The writing system is knowable; which
 * Latin language a word is in is not, and a wrong silent answer is worse
 * than a question. Where the script narrows it to one of the learner's own
 * notebooks it is filed there; where it narrows to several, they are asked;
 * where it fits none of them, they are told, because that is a notebook
 * they have not made yet rather than a mistake they made.
 */
export type Destination =
  /** Exactly one notebook takes this script. Nothing to ask. */
  | { kind: 'certain'; notebook: StoredNotebook }
  /** Several could; the learner picks, starting from the one showing. */
  | { kind: 'ask'; notebooks: StoredNotebook[] }
  /** None could. This is a notebook they have not made yet. */
  | { kind: 'missing'; script: Script }
  /** Nothing to read — digits, punctuation, an empty field. */
  | { kind: 'unknown' };

/**
 * Reads a text and says where it goes.
 *
 * `active` is the notebook the app is showing. It wins a tie, because
 * somebody who has just switched notebooks and started typing means the one
 * they switched to.
 */
export function routeFor(
  text: string,
  notebooks: readonly StoredNotebook[],
  active: StoredNotebook | undefined,
): Destination {
  if (text.trim() === '' || notebooks.length === 0) return { kind: 'unknown' };

  const script = scriptOf(text);
  if (script === 'unknown') return { kind: 'unknown' };

  const languages = [...new Set(notebooks.map((notebook) => notebook.targetLang))];
  const fitting = couldBe(text, languages);
  if (fitting.length === 0) return { kind: 'missing', script };

  const takes = notebooks.filter((notebook) => fitting.includes(notebook.targetLang));
  if (takes.length === 1 && takes[0] !== undefined) {
    // Settled, and settled on the notebook already showing: there is
    // nothing to tell anybody. The line is worth a row only when the word
    // is about to land somewhere other than where they are looking.
    return takes[0].id === active?.id ? { kind: 'unknown' } : { kind: 'certain', notebook: takes[0] };
  }

  // The one being shown goes first: it is the likeliest answer and the one
  // a learner scans for.
  const ordered = [...takes].sort((a, b) => Number(b.id === active?.id) - Number(a.id === active?.id));
  return { kind: 'ask', notebooks: ordered };
}

/**
 * The notebook to file into without asking, if there is one.
 *
 * `ask` resolves to the notebook being shown when it is among the
 * candidates: the question is worth putting on screen, but it must not stop
 * somebody who is simply adding a word to the notebook they are looking at.
 */
export function settles(
  destination: Destination,
  active: StoredNotebook | undefined,
): StoredNotebook | undefined {
  switch (destination.kind) {
    case 'certain':
      return destination.notebook;
    case 'ask':
      return destination.notebooks.find((notebook) => notebook.id === active?.id) ?? destination.notebooks[0];
    default:
      return active;
  }
}

/**
 * The languages worth offering for a script nobody has a notebook for.
 *
 * Capped, because a script with one language is an answer and a script with
 * fifteen is a list: the picker in the new-notebook sheet is better at that
 * than a row of buttons.
 */
export const OFFERED_LANGUAGES = 3;

/** Whether this text is written in the notebook's own language. */
export function belongsIn(text: string, notebook: StoredNotebook): boolean {
  const fitting = couldBe(text, [notebook.targetLang] as LanguageCode[]);
  return fitting.length > 0 || scriptOf(text) === 'unknown';
}
